    def retranslateUi(self, Form):
        _translate = QtCore.QCoreApplication.translate
        self.btn_export_motion_data.setToolTip(_translate("Form", "<p>Saves the results of step 3 as a table with one row per group. A dialog lets you choose the grouping (every grouping you analysed is available), the metrics, and the format: .csv, .xlsx (with extra sheets listing the file's metadata and each metric's unit) or .json. Needs step 3.</p>"))
        self.btn_plot_summary.setToolTip(_translate("Form", "<p>Opens a summary figure of the last motion analysis (step 3): a map of where sarcomeres were tracked and how completely, a map of the groups, the groups' length and length-change traces, and a raster of every sarcomere's length change, over one averaged beat if the 'pool' grouping has been analysed, otherwise over the whole recording. Myofibril and LOI groupings add a map of the groups coloured by beating rate. If you regrouped after step 3, run step 3 again first.</p>"))
        self.dsb_motion_slen_upper.setToolTip(_translate("Form", "<p>Only sarcomere lengths within this range enter a group's length trace; lengths outside are treated as missing in that frame, as they are usually mis-measurements. The same range applies to the per-sarcomere velocities used to compare sarcomeres within a group. Narrow it if implausible lengths distort the group traces; widen it for strongly stretched or contracted preparations. Default 1–3 µm.</p>"))
        self.label_motion_slen_max.setToolTip(_translate("Form", "<p>Only sarcomere lengths within this range enter a group's length trace; lengths outside are treated as missing in that frame, as they are usually mis-measurements. The same range applies to the per-sarcomere velocities used to compare sarcomeres within a group. Narrow it if implausible lengths distort the group traces; widen it for strongly stretched or contracted preparations. Default 1–3 µm.</p>"))
        self.dsb_motion_slen_lower.setToolTip(_translate("Form", "<p>Only sarcomere lengths within this range enter a group's length trace; lengths outside are treated as missing in that frame, as they are usually mis-measurements. The same range applies to the per-sarcomere velocities used to compare sarcomeres within a group. Narrow it if implausible lengths distort the group traces; widen it for strongly stretched or contracted preparations. Default 1–3 µm.</p>"))
        self.label_motion_slen_min.setToolTip(_translate("Form", "<p>Only sarcomere lengths within this range enter a group's length trace; lengths outside are treated as missing in that frame, as they are usually mis-measurements. The same range applies to the per-sarcomere velocities used to compare sarcomeres within a group. Narrow it if implausible lengths distort the group traces; widen it for strongly stretched or contracted preparations. Default 1–3 µm.</p>"))
        self.label_motion_filter_po.setToolTip(_translate("Form", "<p>Order of the polynomial fitted in each window of the velocity filter. A higher order follows sharp velocity peaks more closely but lets more noise through; a lower order smooths more. Always kept below 'window'. Default 5.</p>"))
        self.label_motion_filter_wl.setToolTip(_translate("Form", "<p>Number of frames in the sliding window of the velocity filter. A longer window gives smoother velocities but flattens fast peaks, so peak velocities come out lower; a shorter one keeps the peaks but is noisier. It is counted in frames, not seconds: 13 frames span 0.13 s at 100 frames/s but 0.65 s at 20 frames/s, so lower it for slow recordings. 'Polyorder' is kept below it. Default 13.</p>"))
        self.cb_loi_linkage.setToolTip(_translate("Form", "<p>How the distance between two clusters of lines is measured when deciding whether to merge them (see 'Cluster threshold'). single (default): the closest pair of lines, so clusters can grow along chains of lines; complete: the most distant pair, giving compact clusters; average: the mean over all pairs. Not used by random_line.</p>"))
        self.label_loi_linkage.setToolTip(_translate("Form", "<p>How the distance between two clusters of lines is measured when deciding whether to merge them (see 'Cluster threshold'). single (default): the closest pair of lines, so clusters can grow along chains of lines; complete: the most distant pair, giving compact clusters; average: the mean over all pairs. Not used by random_line.</p>"))
        self.dsb_loi_cluster_threshold.setToolTip(_translate("Form", "<p>Candidate lines that run close together are clustered as copies of the same myofibril, and the LOIs are taken one per cluster. Closeness is the Hausdorff distance: the largest distance from any point of one line to the nearest point of the other. A larger threshold merges lines into fewer, larger clusters, so LOIs lie further apart but neighbouring myofibrils may be merged; a smaller one gives more clusters, and two LOIs may land on the same myofibril. Default 2.5 µm. Not used by random_line.</p>"))
        self.label_loi_cluster.setToolTip(_translate("Form", "<p>Candidate lines that run close together are clustered as copies of the same myofibril, and the LOIs are taken one per cluster. Closeness is the Hausdorff distance: the largest distance from any point of one line to the nearest point of the other. A larger threshold merges lines into fewer, larger clusters, so LOIs lie further apart but neighbouring myofibrils may be merged; a smaller one gives more clusters, and two LOIs may land on the same myofibril. Default 2.5 µm. Not used by random_line.</p>"))
        self.dsb_loi_length_upper.setToolTip(_translate("Form", "<p>Minimum and maximum length of a candidate line (left and right box), measured as the sum of its sarcomere lengths; lines outside are discarded before clustering (the maximum itself is excluded). Works like the sarcomere-number limits, but in µm. Default 0–200 µm, which in practice filters nothing.</p>"))
        self.dsb_loi_length_lower.setToolTip(_translate("Form", "<p>Minimum and maximum length of a candidate line (left and right box), measured as the sum of its sarcomere lengths; lines outside are discarded before clustering (the maximum itself is excluded). Works like the sarcomere-number limits, but in µm. Default 0–200 µm, which in practice filters nothing.</p>"))
        self.label_loi_length.setToolTip(_translate("Form", "<p>Minimum and maximum length of a candidate line (left and right box), measured as the sum of its sarcomere lengths; lines outside are discarded before clustering (the maximum itself is excluded). Works like the sarcomere-number limits, but in µm. Default 0–200 µm, which in practice filters nothing.</p>"))
        self.sb_loi_number_upper.setToolTip(_translate("Form", "<p>Minimum and maximum number of sarcomeres a candidate line may have (left and right box); lines outside are discarded before clustering. The minimum is included, the maximum excluded. Raise the minimum to keep only long, well-ordered myofibrils; raise the maximum for large cells with very long myofibrils. Lines with fewer than 5 sarcomeres are always discarded. Default 10–50.</p>"))
        self.sb_loi_number_lower.setToolTip(_translate("Form", "<p>Minimum and maximum number of sarcomeres a candidate line may have (left and right box); lines outside are discarded before clustering. The minimum is included, the maximum excluded. Raise the minimum to keep only long, well-ordered myofibrils; raise the maximum for large cells with very long myofibrils. Lines with fewer than 5 sarcomeres are always discarded. Default 10–50.</p>"))
        self.label_loi_number.setToolTip(_translate("Form", "<p>Minimum and maximum number of sarcomeres a candidate line may have (left and right box); lines outside are discarded before clustering. The minimum is included, the maximum excluded. Raise the minimum to keep only long, well-ordered myofibrils; raise the maximum for large cells with very long myofibrils. Lines with fewer than 5 sarcomeres are always discarded. Default 10–50.</p>"))
        self.cb_loi_mode.setToolTip(_translate("Form", "<p>How the LOIs are picked from the candidate lines. longest_in_cluster (default): the longest line of each of the largest clusters. fit_straight_line: a straight line fitted through all points of each cluster, extended by 2 µm at both ends. random_from_cluster: a random line from each of the largest clusters. random_line: random lines that pass the filters, without clustering. Lines from the cluster modes follow the actual chain of sarcomeres; fitted lines are matched to the sarcomeres by distance.</p>"))
        self.label_loi_mode.setToolTip(_translate("Form", "<p>How the LOIs are picked from the candidate lines. longest_in_cluster (default): the longest line of each of the largest clusters. fit_straight_line: a straight line fitted through all points of each cluster, extended by 2 µm at both ends. random_from_cluster: a random line from each of the largest clusters. random_line: random lines that pass the filters, without clustering. Lines from the cluster modes follow the actual chain of sarcomeres; fitted lines are matched to the sarcomeres by distance.</p>"))
        self.dsb_loi_threshold_distance.setToolTip(_translate("Form", "<p>Search radius around the predicted position of the next sarcomere while a line grows; the line stops when no sarcomere vector lies within it. A larger radius lets lines bridge small defects and grow longer, but because sarcomere vectors are dense points along each M-band, steps can slip sideways, making lines wavy or jumping to a neighbouring myofibril. A smaller radius gives straighter, shorter lines. Default 0.3 µm.</p>"))
        self.label_loi_thrdist.setToolTip(_translate("Form", "<p>Search radius around the predicted position of the next sarcomere while a line grows; the line stops when no sarcomere vector lies within it. A larger radius lets lines bridge small defects and grow longer, but because sarcomere vectors are dense points along each M-band, steps can slip sideways, making lines wavy or jumping to a neighbouring myofibril. A smaller radius gives straighter, shorter lines. Default 0.3 µm.</p>"))
        self.sb_loi_persistence.setToolTip(_translate("Form", "<p>Number of preceding points on a growing line whose average sarcomere length and orientation predict where the next sarcomere lies. Larger values give straighter lines that ignore local orientation noise but cannot follow strongly bending myofibrils; smaller values follow curves but wander more easily. Each point is one sarcomere. Default 8.</p>"))
        self.label_loi_persistence.setToolTip(_translate("Form", "<p>Number of preceding points on a growing line whose average sarcomere length and orientation predict where the next sarcomere lies. Larger values give straighter lines that ignore local orientation noise but cannot follow strongly bending myofibrils; smaller values follow curves but wander more easily. Each point is one sarcomere. Default 8.</p>"))
        self.dsb_loi_ratio_seeds.setToolTip(_translate("Form", "<p>Fraction of the sarcomere vectors in the reference frame used as start points for growing candidate lines; the start points are drawn at random. A higher ratio grows more candidate lines, so fewer myofibrils are missed, but takes longer; a lower ratio is faster but can miss short or isolated myofibrils. Because sarcomere vectors are dense points along the M-bands, the default 0.1 (10 %) already gives many start points.</p>"))
        self.label_loi_ratio.setToolTip(_translate("Form", "<p>Fraction of the sarcomere vectors in the reference frame used as start points for growing candidate lines; the start points are drawn at random. A higher ratio grows more candidate lines, so fewer myofibrils are missed, but takes longer; a lower ratio is faster but can miss short or isolated myofibrils. Because sarcomere vectors are dense points along the M-bands, the default 0.1 (10 %) already gives many start points.</p>"))
        self.sb_loi_n_lois.setToolTip(_translate("Form", "<p>How many lines of interest are selected; each becomes one group. In the two cluster modes one line is taken from each of the largest clusters (most candidate lines); 'fit_straight_line' keeps the longest fitted lines; 'random_line' picks lines at random. Fewer LOIs result if fewer clusters or lines pass the filters. More LOIs sample more of the cell. Default 4.</p>"))
        self.label_loi_n.setToolTip(_translate("Form", "<p>How many lines of interest are selected; each becomes one group. In the two cluster modes one line is taken from each of the largest clusters (most candidate lines); 'fit_straight_line' keeps the longest fitted lines; 'random_line' picks lines at random. Fewer LOIs result if fewer clusters or lines pass the filters. More LOIs sample more of the cell. Default 4.</p>"))
        Form.setWindowTitle(_translate("Form", "Form"))
        self.groupBox_track.setTitle(_translate("Form", "1. Track sarcomere vectors"))
        self.label_track_along.setToolTip(_translate("Form", "<p>How far a sarcomere vector may move along the sarcomere axis (the myofibril direction, in which sarcomeres shorten during a beat) between two consecutive frames and still continue the same track. Larger values follow faster motion or lower frame rates but risk wrong links; smaller values leave gaps in the tracks during fast contractions. Default 1 µm per frame.</p><p>The value is capped at 60 % of the median sarcomere length (about 1.1 µm for 1.8 µm sarcomeres), so a track can never jump to the next sarcomere; higher entries change nothing.</p>"))
        self.label_track_along.setText(_translate("Form", "Max disp. along [µm]"))
        self.dsb_track_max_disp_along.setToolTip(_translate("Form", "<p>How far a sarcomere vector may move along the sarcomere axis (the myofibril direction, in which sarcomeres shorten during a beat) between two consecutive frames and still continue the same track. Larger values follow faster motion or lower frame rates but risk wrong links; smaller values leave gaps in the tracks during fast contractions. Default 1 µm per frame.</p><p>The value is capped at 60 % of the median sarcomere length (about 1.1 µm for 1.8 µm sarcomeres), so a track can never jump to the next sarcomere; higher entries change nothing.</p>"))
        self.label_track_perp.setToolTip(_translate("Form", "<p>How far a sarcomere vector may move sideways (perpendicular to the sarcomere axis, i.e. along its Z- and M-bands) between two consecutive frames and still continue the same track. Real sideways motion is small, so this is kept much tighter than the 'along' limit: a large sideways step usually means a jump onto a neighbouring myofibril. Raise it slightly if the cell drifts sideways and tracks keep breaking; lower it if tracks swap between neighbouring myofibrils. Default 0.2 µm per frame, capped at 25 % of the median sarcomere length.</p>"))
        self.label_track_perp.setText(_translate("Form", "Max disp. perp [µm]"))
        self.dsb_track_max_disp_perp.setToolTip(_translate("Form", "<p>How far a sarcomere vector may move sideways (perpendicular to the sarcomere axis, i.e. along its Z- and M-bands) between two consecutive frames and still continue the same track. Real sideways motion is small, so this is kept much tighter than the 'along' limit: a large sideways step usually means a jump onto a neighbouring myofibril. Raise it slightly if the cell drifts sideways and tracks keep breaking; lower it if tracks swap between neighbouring myofibrils. Default 0.2 µm per frame, capped at 25 % of the median sarcomere length.</p>"))
        self.label_track_ori.setToolTip(_translate("Form", "<p>Largest change in sarcomere orientation allowed between two frames for a detection to continue a track. Orientations are compared as axes, so 170° and 10° differ by 20°. A smaller tolerance prevents links to structures running at a different angle but can break tracks in disordered or bending regions, where the measured orientation is noisy; a larger one links more freely. Default 45°. 90° switches the check off.</p>"))
        self.label_track_ori.setText(_translate("Form", "Orient. tol. [deg]"))
        self.dsb_track_ori_tol.setToolTip(_translate("Form", "<p>Largest change in sarcomere orientation allowed between two frames for a detection to continue a track. Orientations are compared as axes, so 170° and 10° differ by 20°. A smaller tolerance prevents links to structures running at a different angle but can break tracks in disordered or bending regions, where the measured orientation is noisy; a larger one links more freely. Default 45°. 90° switches the check off.</p>"))
        self.label_track_min_duration.setToolTip(_translate("Form", "<p>Tracks whose sarcomere was actually detected for less than this total time are deleted after tracking. Only frames with a real detection count, not gaps or filled-in frames, and they need not be consecutive. A higher value removes short-lived fragments (noise, sarcomeres flickering in and out) but also drops sarcomeres that are only briefly detected; a lower value keeps more of them. Default 0.08 s. It is converted to a number of frames (at least 1), so below about 19 frames/s a single detection is enough.</p>"))
        self.label_track_min_duration.setText(_translate("Form", "Min. track duration [s]"))
        self.dsb_track_min_duration_s.setToolTip(_translate("Form", "<p>Tracks whose sarcomere was actually detected for less than this total time are deleted after tracking. Only frames with a real detection count, not gaps or filled-in frames, and they need not be consecutive. A higher value removes short-lived fragments (noise, sarcomeres flickering in and out) but also drops sarcomeres that are only briefly detected; a lower value keeps more of them. Default 0.08 s. It is converted to a number of frames (at least 1), so below about 19 frames/s a single detection is enough.</p>"))
        self.label_track_gap.setToolTip(_translate("Form", "<p>When a sarcomere is missed in a few frames inside its track, its length and orientation there are filled in by a straight line between the frames on either side, so brief detection flicker does not punch holes in its length trace. Longer gaps stay empty. Filled frames still count as undetected for coverage and track duration, but their lengths enter the group traces. Longer values fill more holes but can draw a straight line across part of a contraction. Default 0.05 s (at least 1 frame); 0 switches filling off.</p>"))
        self.label_track_gap.setText(_translate("Form", "Max gap interp. [s]"))
        self.dsb_track_max_gap_interp_s.setToolTip(_translate("Form", "<p>When a sarcomere is missed in a few frames inside its track, its length and orientation there are filled in by a straight line between the frames on either side, so brief detection flicker does not punch holes in its length trace. Longer gaps stay empty. Filled frames still count as undetected for coverage and track duration, but their lengths enter the group traces. Longer values fill more holes but can draw a straight line across part of a contraction. Default 0.05 s (at least 1 frame); 0 switches filling off.</p>"))
        self.chk_track_flow_predictor.setToolTip(_translate("Form", "<p>Before linking, moves every sarcomere to where the optical flow of the raw image says it went, instead of assuming it stayed in place. Turn it on when the frame rate is low compared with the motion, i.e. a contraction moves sarcomeres a good part of their length between two frames, and tracks break up or have low coverage. At high frame rates (about 30 frames/s and more) it gives practically the same tracks as off. Extra cost grows with image size and number of frames. Default off.</p>"))
        self.chk_track_flow_predictor.setText(_translate("Form", "Predict motion from image flow (coarse frame rates)"))
        self.chk_track_refine_lengths.setToolTip(_translate("Form", "<p>After tracking, gives each track one sarcomere axis (the median of its detected orientations) and measures its length again along that axis in every frame; the track's position moves to the midpoint between its two Z-bands. Where Z-bands tilt during a contraction (neighbouring myofibrils shortening by different amounts), the spacing normal to them is shorter than along the sarcomere, so without this step shortening is overstated (about 10 % on a 61 frames/s movie) and lengths are noisier from frame to frame. Costs about 0.1 s per frame. Turn it off only for a quick first look. Default on.</p>"))
        self.chk_track_refine_lengths.setText(_translate("Form", "Refine lengths along each track's sarcomere axis"))
        self.btn_track_vectors.setToolTip(_translate("Form", "<p>Step 1. Links the sarcomere vectors from the Structure tab from frame to frame, so each tracked point gets its position, length and orientation over time. Needs a movie and sarcomere vectors in consecutive frames; if the structure analysis covered only part of the movie, you are asked whether to track just those frames. Replaces earlier tracks, so steps 2 and 3 must be run again. Shows the tracked sarcomeres as dots in the viewer. Takes seconds to minutes, depending on movie length and image size.</p>"))
        self.btn_track_vectors.setText(_translate("Form", "1. Track sarcomere vectors"))
        self.groupBox_display.setTitle(_translate("Form", "Display in viewer"))
        self.label_display_color.setToolTip(_translate("Form", "<p>What the sarcomere dots in the viewer are coloured by. ΔSL: change of the sarcomere's length from its resting length (blue shorter, red longer). SL: sarcomere length. Velocity: rate of length change in µm/s, negative while shortening. Group: its group from step 2 (grey = in no group). Coverage: fraction of the tracked frames in which it was detected. Track id: one arbitrary colour per track, to check that identities hold. Grey means no value in that frame. Display only.</p><p>The resting length is the median over the frames in which the cell is not contracting once the 'pool' grouping has been analysed, otherwise the median over all frames.</p>"))
        self.label_display_color.setText(_translate("Form", "Colour by"))
        self.cb_display_color_by.setToolTip(_translate("Form", "<p>What the sarcomere dots in the viewer are coloured by. ΔSL: change of the sarcomere's length from its resting length (blue shorter, red longer). SL: sarcomere length. Velocity: rate of length change in µm/s, negative while shortening. Group: its group from step 2 (grey = in no group). Coverage: fraction of the tracked frames in which it was detected. Track id: one arbitrary colour per track, to check that identities hold. Grey means no value in that frame. Display only.</p><p>The resting length is the median over the frames in which the cell is not contracting once the 'pool' grouping has been analysed, otherwise the median over all frames.</p>"))
        self.label_display_limit.setToolTip(_translate("Form", "<p>Sets the ΔSL colour scale to run from minus this value (full blue) to plus this value (full red); larger changes get the end colour. Lower it to bring out small length changes; raise it if most sarcomeres look saturated. Default 0 µm, which means automatic: the 99th percentile of |ΔSL| over all sarcomeres and frames. Display only; only used when 'Colour by' is ΔSL.</p>"))
        self.label_display_limit.setText(_translate("Form", "ΔSL colour limit [µm]"))
        self.dsb_display_dsl_limit.setToolTip(_translate("Form", "<p>Sets the ΔSL colour scale to run from minus this value (full blue) to plus this value (full red); larger changes get the end colour. Lower it to bring out small length changes; raise it if most sarcomeres look saturated. Default 0 µm, which means automatic: the 99th percentile of |ΔSL| over all sarcomeres and frames. Display only; only used when 'Colour by' is ΔSL.</p>"))
        self.chk_display_sarcomeres.setToolTip(_translate("Form", "<p>Shows or hides the 'Sarcomeres' layer: every tracked sarcomere as a dot at its position in the current frame, coloured as set in 'Colour by'. A dot appears only in frames in which the sarcomere was actually detected. Click a dot to select it: the members of its group are ringed in yellow and its length traces open in a panel below the viewer. Default on.</p>"))
        self.chk_display_sarcomeres.setText(_translate("Form", "Sarcomeres"))
        self.chk_display_groups.setToolTip(_translate("Form", "<p>Shows or hides the 'Groups' layer. For the myofibril and LOI groupings it draws one line per group through its sarcomeres at the reference frame, coloured and numbered by group (numbers only up to 30 groups). Click a line to select that group: its sarcomeres are ringed in yellow and the group's traces open in a panel below the viewer. Other groupings draw no lines; set 'Colour by' to Group to see them. Default on.</p>"))
        self.chk_display_groups.setText(_translate("Form", "Groups (lines)"))
        self.label_display_hint.setText(_translate("Form", "Click a sarcomere or a group line: its group is highlighted and its SL / ΔSL traces open in a panel below the viewer."))
        self.groupBox_group.setTitle(_translate("Form", "2. Group tracks"))
        self.label_group_by.setToolTip(_translate("Form", "<p>How the tracked sarcomeres are combined into groups; step 3 analyses one length trace per group. pool: all tracks in one group (whole field of view). mband: one group per M-band at the reference frame. myofibril: one group per myofibril line from the Structure tab, sarcomeres ordered along it. domain: one group per sarcomere domain from the Structure tab. loi: one group per line of interest, drawn by you or detected automatically, ordered along it.</p><p>myofibril and loi order the sarcomeres along their line and leave out tracks that drifted more than one sarcomere length away from their neighbours. Default myofibril.</p>"))
        self.label_group_by.setText(_translate("Form", "Group by"))
        self.cb_group_by.setToolTip(_translate("Form", "<p>How the tracked sarcomeres are combined into groups; step 3 analyses one length trace per group. pool: all tracks in one group (whole field of view). mband: one group per M-band at the reference frame. myofibril: one group per myofibril line from the Structure tab, sarcomeres ordered along it. domain: one group per sarcomere domain from the Structure tab. loi: one group per line of interest, drawn by you or detected automatically, ordered along it.</p><p>myofibril and loi order the sarcomeres along their line and leave out tracks that drifted more than one sarcomere length away from their neighbours. Default myofibril.</p>"))
        self.label_group_ref.setToolTip(_translate("Form", "<p>The frame whose structure decides which group each sarcomere belongs to: the M-band, myofibril line, domain or LOI it lies on in that frame. Automatic LOI detection also runs on this frame, and drawn LOIs are matched to the sarcomere positions in it. Not used for 'pool'. Choose a frame with the cell at rest and the structure well detected; it must be a tracked frame and, for myofibril or domain, analysed in the Structure tab. Default 0 (the first frame).</p>"))
        self.label_group_ref.setText(_translate("Form", "Reference frame"))
        self.sb_group_reference_frame.setToolTip(_translate("Form", "<p>The frame whose structure decides which group each sarcomere belongs to: the M-band, myofibril line, domain or LOI it lies on in that frame. Automatic LOI detection also runs on this frame, and drawn LOIs are matched to the sarcomere positions in it. Not used for 'pool'. Choose a frame with the cell at rest and the structure well detected; it must be a tracked frame and, for myofibril or domain, analysed in the Structure tab. Default 0 (the first frame).</p>"))
        self.label_group_cov.setToolTip(_translate("Form", "<p>Sarcomeres detected in fewer than this fraction of the tracked frames are left out of all groups. Higher values keep only well-tracked sarcomeres and give cleaner group traces but fewer members; lower values keep more. Whenever 'Group by' changes, it is reset to 0.1 for myofibril and LOI (a chain of sarcomeres should not get holes) and to 0.5 for the other groupings; you can then change it. Frames filled by gap interpolation do not count. Range 0–1.</p>"))
        self.label_group_cov.setText(_translate("Form", "Min. coverage"))
        self.dsb_group_min_coverage.setToolTip(_translate("Form", "<p>Sarcomeres detected in fewer than this fraction of the tracked frames are left out of all groups. Higher values keep only well-tracked sarcomeres and give cleaner group traces but fewer members; lower values keep more. Whenever 'Group by' changes, it is reset to 0.1 for myofibril and LOI (a chain of sarcomeres should not get holes) and to 0.5 for the other groupings; you can then change it. Frames filled by gap interpolation do not count. Range 0–1.</p>"))
        self.label_group_min_size.setToolTip(_translate("Form", "<p>Groups with fewer member tracks than this are dissolved; their sarcomeres stay ungrouped and are not analysed. In myofibril and LOI groups a member is one sarcomere along the line, so e.g. 6 removes myofibril fragments of 1–5 sarcomeres whose average trace is too noisy. In the other groupings every tracked M-band point is a member, so counts are much larger. Groups are renumbered afterwards, except domain and LOI groups. Default 1 (keep all).</p>"))
        self.label_group_min_size.setText(_translate("Form", "Min. group size"))
        self.sb_group_min_group_size.setToolTip(_translate("Form", "<p>Groups with fewer member tracks than this are dissolved; their sarcomeres stay ungrouped and are not analysed. In myofibril and LOI groups a member is one sarcomere along the line, so e.g. 6 removes myofibril fragments of 1–5 sarcomeres whose average trace is too noisy. In the other groupings every tracked M-band point is a member, so counts are much larger. Groups are renumbered afterwards, except domain and LOI groups. Default 1 (keep all).</p>"))
        self.btn_group_tracks.setToolTip(_translate("Form", "<p>Step 2. Sorts the tracked sarcomeres into groups as set in 'Group by', using the reference frame. With 'Group by = loi' it uses the lines you drew or, if there are none, detects LOIs automatically first. Needs step 1 and, for myofibril or domain, the matching Structure-tab analysis. Takes seconds and does not change the tracks, so you can regroup freely; run step 3 again afterwards. Updates the group colours and group lines in the viewer.</p>"))
        self.btn_group_tracks.setText(_translate("Form", "2. Group tracks"))
        self.btn_draw_lois.setToolTip(_translate("Form", "<p>Adds a drawing layer ('DrawnLOIs') to the viewer for your own lines of interest. Click points along a myofibril and double-click to finish a line; draw as many as you like. With 'Group by = loi', step 2 then groups the sarcomeres along your lines: at the reference frame, the tracked points within half a sarcomere length of a line, one per sarcomere along it. Delete the lines (or the layer) to go back to automatic detection. Only shown when 'Group by' is loi.</p>"))
        self.btn_draw_lois.setText(_translate("Form", "Draw LOIs on movie…"))
        self.groupBox_loi_detect.setToolTip(_translate("Form", "<p>Settings for finding lines of interest (LOIs) automatically in the reference frame: candidate lines are grown along the myofibrils from random start points, filtered, clustered into near-duplicates, and one line per cluster is kept. Used only when 'Group by' is loi and no lines were drawn. Tick the title to show the settings; ticking does not switch detection on or off. Because the start points are random, the LOIs can differ slightly between runs.</p>"))
        self.groupBox_loi_detect.setTitle(_translate("Form", "LOI auto-detection (advanced)"))
        self.label_loi_n.setText(_translate("Form", "Number of LOIs"))
        self.label_loi_ratio.setText(_translate("Form", "Seed ratio"))
        self.label_loi_persistence.setText(_translate("Form", "Persistence"))
        self.label_loi_thrdist.setText(_translate("Form", "Growth dist. [µm]"))
        self.label_loi_mode.setText(_translate("Form", "Mode"))
        self.label_loi_number.setText(_translate("Form", "Sarcomere # limits"))
        self.label_loi_length.setText(_translate("Form", "Length limits [µm]"))
        self.label_loi_cluster.setText(_translate("Form", "Cluster threshold [µm]"))
        self.label_loi_linkage.setText(_translate("Form", "Linkage"))
        self.groupBox_analyze.setTitle(_translate("Form", "3. Analyze track motion"))
        self.label_motion_agg.setToolTip(_translate("Form", "<p>How the lengths of a group's sarcomeres are combined, frame by frame, into one length trace SL(t), which the contraction analysis then uses. mean (default): the average of the members measured in that frame. median: the middle value, less affected by a few mis-measured tracks. Only lengths within the sarcomere-length range count. The spread between members (standard deviation, quartiles) is stored either way.</p>"))
        self.label_motion_agg.setText(_translate("Form", "Group signal"))
        self.cb_motion_aggregate.setToolTip(_translate("Form", "<p>How the lengths of a group's sarcomeres are combined, frame by frame, into one length trace SL(t), which the contraction analysis then uses. mean (default): the average of the members measured in that frame. median: the middle value, less affected by a few mis-measured tracks. Only lengths within the sarcomere-length range count. The spread between members (standard deviation, quartiles) is stored either way.</p>"))
        self.label_motion_thr.setToolTip(_translate("Form", "<p>ContractionNet, a neural network, reads each group's length trace and gives every frame a probability (0–1) that the group is contracting; frames above this threshold count as contracting, and a contraction must also reach the model's confidence peak (0.85, read from the model file) at least once. Raise the threshold if noise or drift is detected as contractions; lower it if weak beats are missed. Default 0.45, the value the bundled model was tuned for (read from the model file); leave it unless the detected contractions look wrong.</p>"))
        self.label_motion_thr.setText(_translate("Form", "Contr. threshold"))
        self.dsb_motion_threshold.setToolTip(_translate("Form", "<p>ContractionNet, a neural network, reads each group's length trace and gives every frame a probability (0–1) that the group is contracting; frames above this threshold count as contracting, and a contraction must also reach the model's confidence peak (0.85, read from the model file) at least once. Raise the threshold if noise or drift is detected as contractions; lower it if weak beats are missed. Default 0.45, the value the bundled model was tuned for (read from the model file); leave it unless the detected contractions look wrong.</p>"))
        self.label_motion_ctmin.setToolTip(_translate("Form", "<p>Contractions shorter than this are discarded as noise. A higher value removes brief false detections but can delete real short contractions, for example in fast-paced cells; a lower value keeps them. Default 0.2 s. It is rounded to the nearest frame and acts only when that gives at least 2 frames (with the default, from 7.5 frames/s up).</p>"))
        self.label_motion_ctmin.setText(_translate("Form", "Min. contr. time [s]"))
        self.dsb_motion_contr_time_min.setToolTip(_translate("Form", "<p>Contractions shorter than this are discarded as noise. A higher value removes brief false detections but can delete real short contractions, for example in fast-paced cells; a lower value keeps them. Default 0.2 s. It is rounded to the nearest frame and acts only when that gives at least 2 frames (with the default, from 7.5 frames/s up).</p>"))
        self.label_motion_buffer.setToolTip(_translate("Form", "<p>A contraction that starts within this many frames of the beginning of the recording, or ends within this many frames of its end, counts as incomplete, because part of it may lie outside the recording. It is kept as a contraction and for the beating rate, but measures that need its full course (contraction time, time to peak, relaxation times, or a peak at the cut edge) are left empty. Default 3 frames.</p>"))
        self.label_motion_buffer.setText(_translate("Form", "Buffer [frames]"))
        self.sb_motion_buffer_frames.setToolTip(_translate("Form", "<p>A contraction that starts within this many frames of the beginning of the recording, or ends within this many frames of its end, counts as incomplete, because part of it may lie outside the recording. It is kept as a contraction and for the beating rate, but measures that need its full course (contraction time, time to peak, relaxation times, or a peak at the cut edge) are left empty. Default 3 frames.</p>"))
        self.label_motion_minvalid.setToolTip(_translate("Form", "<p>Groups whose length trace has a value in fewer than this fraction of the frames are not analysed: no contractions are detected and all their results stay empty. A frame has no value when none of the group's sarcomeres was measured in it within the sarcomere-length range. Lower it to analyse sparsely tracked groups, at the cost of less reliable results. Default 0.5 (50 % of frames).</p>"))
        self.label_motion_minvalid.setText(_translate("Form", "Min. valid frames"))
        self.dsb_motion_min_valid_frames.setToolTip(_translate("Form", "<p>Groups whose length trace has a value in fewer than this fraction of the frames are not analysed: no contractions are detected and all their results stay empty. A frame has no value when none of the group's sarcomeres was measured in it within the sarcomere-length range. Lower it to analyse sparsely tracked groups, at the cost of less reliable results. Default 0.5 (50 % of frames).</p>"))
        self.label_motion_filter.setToolTip(_translate("Form", "<p>Savitzky-Golay filter used to compute velocities from the length traces: it fits a polynomial in a sliding window of frames. It sets the peak shortening and lengthening velocities of each group and the velocities used to compare the sarcomeres within a group; contraction detection and length changes are not affected. 'window' sets how many frames are smoothed, 'polyorder' how flexibly the fit follows the trace. Defaults 13 frames and order 5.</p>"))
        self.label_motion_filter.setText(_translate("Form", "Smoothing filter"))
        self.label_motion_filter_wl.setText(_translate("Form", "window"))
        self.sb_motion_filter_wl.setToolTip(_translate("Form", "<p>Number of frames in the sliding window of the velocity filter. A longer window gives smoother velocities but flattens fast peaks, so peak velocities come out lower; a shorter one keeps the peaks but is noisier. It is counted in frames, not seconds: 13 frames span 0.13 s at 100 frames/s but 0.65 s at 20 frames/s, so lower it for slow recordings. 'Polyorder' is kept below it. Default 13.</p>"))
        self.label_motion_filter_po.setText(_translate("Form", "polyorder"))
        self.sb_motion_filter_po.setToolTip(_translate("Form", "<p>Order of the polynomial fitted in each window of the velocity filter. A higher order follows sharp velocity peaks more closely but lets more noise through; a lower order smooths more. Always kept below 'window'. Default 5.</p>"))
        self.label_motion_slen.setToolTip(_translate("Form", "<p>Only sarcomere lengths within this range enter a group's length trace; lengths outside are treated as missing in that frame, as they are usually mis-measurements. The same range applies to the per-sarcomere velocities used to compare sarcomeres within a group. Narrow it if implausible lengths distort the group traces; widen it for strongly stretched or contracted preparations. Default 1–3 µm.</p>"))
        self.label_motion_slen.setText(_translate("Form", "Sarc. length [µm]"))
        self.label_motion_slen_min.setText(_translate("Form", "Min:"))
        self.label_motion_slen_max.setText(_translate("Form", "Max:"))
        self.btn_analyze_track_motion.setToolTip(_translate("Form", "<p>Step 3. For each group from step 2, combines its sarcomeres' lengths into one trace, detects the contractions with ContractionNet and measures them: beating rate, resting length, contraction amplitude, shortening and lengthening velocity, contraction and relaxation times, and how synchronously the sarcomeres in the group move. Needs step 2 and the frame time. Results are kept per grouping, so pool, myofibril and others can be analysed one after another and exported separately. Usually takes seconds.</p>"))
        self.btn_analyze_track_motion.setText(_translate("Form", "3. Analyze track motion"))
        self.btn_analyze_motion.setToolTip(_translate("Form", "<p>Runs steps 1, 2 and 3 one after another with the current settings: track sarcomere vectors, group tracks, analyse track motion. Check the settings of all three steps first. Needs sarcomere vectors from the Structure tab and, depending on 'Group by', myofibrils or domains. Takes as long as the three steps together, mostly the tracking.</p>"))
        self.btn_analyze_motion.setText(_translate("Form", "Track → Group → Analyze (all)"))
        self.groupBox_output.setTitle(_translate("Form", "Detail & output"))
        self.label_detail_group.setToolTip(_translate("Form", "<p>Which group to show with 'Show group detail'. The numbers are the group numbers in the viewer; clicking a sarcomere or a group line in the viewer selects its group here. Available after grouping, for every kind.</p>"))
        self.label_detail_group.setText(_translate("Form", "Group"))
        self.cb_detail_group.setToolTip(_translate("Form", "<p>Which group to show with 'Show group detail'. The numbers are the group numbers in the viewer; clicking a sarcomere or a group line in the viewer selects its group here. Available after grouping, for every kind.</p>"))
        self.btn_show_group_detail.setToolTip(_translate("Form", "<p>Plots the selected group from the results of step 3: the length change of each of its sarcomeres, a phase-space plot (length change against velocity), a map of popping events (a sarcomere lengthening more than 0.25 µm beyond its resting length during a contraction) and, for myofibril and LOI groups, the Z-band positions along the line over time.</p>"))
        self.btn_show_group_detail.setText(_translate("Form", "Show group detail"))
        self.btn_plot_summary.setText(_translate("Form", "Plot summary"))
